  })
  agents.push({
    id: 'curation-data-scorekeeper',
    name: 'Usage Scorekeeper',
    role: 'scorekeeper',
    division: 'curation-data',
    route: { provider: 'deepseek-official', model: 'deepseek-v4-pro' },
    preset: 'reviewing',
    skills: [],
    tools: ['session_query'],
    source: cite(root, 'packages/llm/token-meter/README.md'),
