/** One governance standard: its id, display name, grounding source, and the skill (if any) that applies. */
interface GovernanceStandard {
  id: string
  name: string
  source: string
  skill?: string
}

const GOVERNANCE_STANDARDS: readonly GovernanceStandard[] = [
  {
    id: 'label-taxonomy',
