212	 * @param root - directory to walk.
213	 * @returns absolute file paths.
214	 */
215	function walkFiles(root: string): string[] {
216	  const out: string[] = []
217	  const stack = [root]
218	  while (stack.length > 0 && out.length < MAX_WALK_FILES) {
219	    const dir = stack.pop()!
220	    let entries: Dirent[]
221	    try {
